style.css:
/* Основной фон */
body {
    background-color: #2C2C2C; /* Темно-серый фон с теплым оттенком */
    color: #DADADA; /* Светло-серый текст */
    font-family: 'Segoe UI', Tahoma, Geneva, Verdana, sans-serif;
}

/* Заголовки */
h1, h2, h3, h4, h5, h6 {
    color: #FFAE42; /* Теплый оранжевый оттенок */
    font-weight: bold;
}

/* Списки */
ul {
    padding-left: 20px;
    color: #D8D8D8;
}

/* Ссылки */
a {
    color: #FFA07A; /* Светло-оранжевый */
    text-decoration: none;
}

a:hover {
    text-decoration: underline;
    color: #FF8C00; /* Более насыщенный оранжевый при наведении */
}

/* Кодовые блоки */
pre, code {
    background-color: #3C3C3C; /* Темный серый для кодовых блоков */
    color: #E0E0E0; /* Светло-серый текст */
    padding: 8px;
    border-radius: 4px;
}

/* Блоки цитирования */
blockquote {
    border-left: 4px solid #FFAE42; /* Оранжевая линия слева */
    padding-left: 12px;
    color: #D1D1D1; /* Светло-серый текст */
    background-color: #2F2F2F; /* Темно-серый фон для блока цитирования */
    margin-left: 0;
}

/* Подчеркивания */
hr {
    border-color: #565656; /* Серый цвет для разделителей */
}
